function App() {
  const [data, setData] = useState([]);

  const fetchData = async () => {
    try {
      const result = await mcp.call("read_cells", {
        sheet: BINDING.sheet,
        startRow: BINDING.startRow,
        startCol: BINDING.startCol,
        endRow: BINDING.endRow,
        endCol: BINDING.endCol
      });

      if (result && result.cells) {
        const rows = result.cells.slice(1);
        const totals = {};

        rows.forEach(row => {
          const region = row[1];
          const revenue = parseFloat(row[2]) || 0;
          if (region) {
            totals[region] = (totals[region] || 0) + revenue;
          }
        });

        setData(Object.entries(totals).map(([region, total]) => ({ region, total })));
      }
    } catch (e) {
      console.error("Error fetching data", e);
    }
  };

  useEffect(() => {
    fetchData();
    const unsub = mcp.subscribe(["cells_changed", "recalc_complete"], BINDING.sheet, fetchData);
    return () => { if (unsub && typeof unsub === 'function') unsub(); };
  }, []);

  return h("div", { style: { fontFamily: "system-ui", padding: "16px" } }, [
    h("h2", { style: { fontSize: "18px", marginBottom: "12px" } }, "Revenue by Region"),
    h("table", { style: { width: "100%", borderCollapse: "collapse" } }, [
      h("thead", null, [
        h("tr", { style: { borderBottom: "1px solid #ccc" } }, [
          h("th", { style: { textAlign: "left", padding: "8px" } }, "Region"),
          h("th", { style: { textAlign: "right", padding: "8px" } }, "Total Revenue")
        ])
      ]),
      h("tbody", null, data.map((item, i) => 
        h("tr", { key: i, style: { borderBottom: "1px solid #eee" } }, [
          h("td", { style: { padding: "8px" } }, item.region),
          h("td", { style: { padding: "8px", textAlign: "right" } }, item.total.toLocaleString(undefined, { style: 'currency', currency: 'USD' }))
        ])
      ))
    ])
  ]);
}
